-- consent: Consent, NoSummon and PK
DO $do$
DECLARE v_id integer;
BEGIN
  SELECT id INTO v_id FROM "HelpEntry" WHERE keywords[1] = 'consent' ORDER BY id LIMIT 1;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM "HelpEntry" WHERE 'consent' = ANY(keywords) ORDER BY id LIMIT 1;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO "HelpEntry"
      (keywords, title, content, min_level, category, usage, source_file, updated_at)
    VALUES (
      ARRAY['consent', 'no-summon', 'summons', 'summoning', 'consent-and-nosummon']::text[],
      'Consent, NoSummon and PK',
      $help$Three switches control how other players can affect you. Each is a toggle:
type the command once to turn it on and again to turn it off. "flags" lists
the ones you have set.

NOSUMMON
  Someone casting summon on you doesn't move you straight away. You are
  told who wants to summon you and where to, and have 30 seconds to answer:

    accept    go to the caster.
    decline   stay where you are.

  "nosummon" skips the prompt altogether: every summon is refused
  silently and the caster just sees that you are not accepting summons.
  It is handy when you are away from the keyboard. Turn it off again to
  get the prompts back. Staff with the summon permission, and players with
  PK switched on, can't be shielded this way (see PK).

PK
  "pk" marks you as willing to take part in player-versus-player play. While
  it is on, area attacks in your room count you as an enemy and summons reach
  you without a prompt. Leave it off unless you want that.

CONSENT
  "consent" toggles your CONSENT flag, which marks you as trusting other
  players for shared interactions. Today the flag is only recorded; it does
  not change who can loot you. Your own corpse is always safe: only you
  (and staff) can take things from it, whether or not consent is set.

See also: MAGIC, GROUPS, FLAGS.$help$,
      0,
      'guide',
      'consent | nosummon | pk | flags',
      'data/help/consent.md',
      now()
    );
  ELSE
    UPDATE "HelpEntry" SET
      keywords = ARRAY['consent', 'no-summon', 'summons', 'summoning', 'consent-and-nosummon']::text[],
      title = 'Consent, NoSummon and PK',
      content = $help$Three switches control how other players can affect you. Each is a toggle:
type the command once to turn it on and again to turn it off. "flags" lists
the ones you have set.

NOSUMMON
  Someone casting summon on you doesn't move you straight away. You are
  told who wants to summon you and where to, and have 30 seconds to answer:

    accept    go to the caster.
    decline   stay where you are.

  "nosummon" skips the prompt altogether: every summon is refused
  silently and the caster just sees that you are not accepting summons.
  It is handy when you are away from the keyboard. Turn it off again to
  get the prompts back. Staff with the summon permission, and players with
  PK switched on, can't be shielded this way (see PK).

PK
  "pk" marks you as willing to take part in player-versus-player play. While
  it is on, area attacks in your room count you as an enemy and summons reach
  you without a prompt. Leave it off unless you want that.

CONSENT
  "consent" toggles your CONSENT flag, which marks you as trusting other
  players for shared interactions. Today the flag is only recorded; it does
  not change who can loot you. Your own corpse is always safe: only you
  (and staff) can take things from it, whether or not consent is set.

See also: MAGIC, GROUPS, FLAGS.$help$,
      min_level = 0,
      category = 'guide',
      usage = 'consent | nosummon | pk | flags',
      source_file = 'data/help/consent.md',
      updated_at = now()
    WHERE id = v_id;
  END IF;
END
